/* MCU Tracker Central Auth v1.6.0 */
const MCU_SB_URL="https://svnrfyqloiludzvnylyp.supabase.co";
const MCU_SB_KEY="sb_publishable_SLhIn3mSi8EzBym_BnfiqA_IUR_3xxm";
const MCU_ACCOUNT_FN=MCU_SB_URL+"/functions/v1/mcu-account";
const MCU_CENTRAL_SESSION_KEY="MCU_TRACKER_CENTRAL_SESSION_V1";
function centralEmail(username){return userKey(username)+"@users.mcutracker.local"}
function centralHeaders(token=""){const h={apikey:MCU_SB_KEY,"Content-Type":"application/json"};if(token)h.Authorization="Bearer "+token;return h}
async function centralJson(url,opts={}){const r=await fetch(url,opts);let data={};try{data=await r.json()}catch{}if(!r.ok){const e=new Error(data?.error_description||data?.msg||data?.message||data?.error||("HTTP "+r.status));e.status=r.status;throw e}return data}
function saveCentralSession(s){localStorage.setItem(MCU_CENTRAL_SESSION_KEY,JSON.stringify(s))}
function loadCentralSession(){try{return JSON.parse(localStorage.getItem(MCU_CENTRAL_SESSION_KEY)||"null")}catch{return null}}
function clearCentralSession(){localStorage.removeItem(MCU_CENTRAL_SESSION_KEY)}
async function refreshCentralSession(s){if(!s?.refresh_token)throw new Error("session_expired");const d=await centralJson(MCU_SB_URL+"/auth/v1/token?grant_type=refresh_token",{method:"POST",headers:centralHeaders(),body:JSON.stringify({refresh_token:s.refresh_token})});saveCentralSession(d);return d}
async function centralUser(session){let s=session||loadCentralSession();if(!s?.access_token)throw new Error("no_session");try{return {session:s,user:await centralJson(MCU_SB_URL+"/auth/v1/user",{headers:centralHeaders(s.access_token)})}}catch(e){if(e.status===401){s=await refreshCentralSession(s);return {session:s,user:await centralJson(MCU_SB_URL+"/auth/v1/user",{headers:centralHeaders(s.access_token)})}}throw e}}
async function centralProfile(session){const {session:s,user}=await centralUser(session);const rows=await centralJson(MCU_SB_URL+"/rest/v1/mcu_profiles?select=id,username,display_name,role&id=eq."+encodeURIComponent(user.id),{headers:centralHeaders(s.access_token)});if(!rows?.length)throw new Error("profile_missing");return {session:s,user,profile:rows[0]}}
async function centralLogin(username,password){const d=await centralJson(MCU_SB_URL+"/auth/v1/token?grant_type=password",{method:"POST",headers:centralHeaders(),body:JSON.stringify({email:centralEmail(username),password})});saveCentralSession(d);return centralProfile(d)}
async function centralRegister(username,password,displayName,bootstrapCode=""){const action=userKey(username)==="ovztur"?"bootstrap_superadmin":"register";await centralJson(MCU_ACCOUNT_FN,{method:"POST",headers:centralHeaders(),body:JSON.stringify({action,username:userKey(username),password,display_name:displayName||username,bootstrap_code:bootstrapCode})});return centralLogin(username,password)}
function centralApplyUser(x){const p=x.profile;currentUser={key:userKey(p.username),username:p.username,displayName:p.display_name||p.username,role:p.role,isPrimaryAdmin:p.username==="ovztur"};users={[currentUser.key]:currentUser};loadCurrentUserState();applyTheme(currentTheme());updateAccountUI();hideAuth();currentCategory="doomsday";renderCurrent();updateProgress();refreshIMDbRatings(false)}
isSuperAdmin=function(){return userKey(currentUser?.username||"")==="ovztur"&&currentUser?.role==="superadmin"};
isAdmin=function(){return currentUser?.role==="admin"||currentUser?.role==="superadmin"||isSuperAdmin()};
enforcePrimaryAdmin=function(){};
saveUsers=function(){};
renderAuth=function(mode="login"){
 const card=document.getElementById("authCard"),register=mode==="register",setup=mode==="setup";
 const sub=setup?"Ana Admin kurulumu":register?"Merkezi hesap oluştur":"İnternet hesabına giriş";
 const userExtra=setup?'value="ovztur" readonly':'';
 const displayField=register?'<div class="auth-field"><label>Profil adı</label><input id="authDisplay" maxlength="24" placeholder="Örn. Peter"></div>':'';
 const confirmField=(register||setup)?'<div class="auth-field"><label>Şifre tekrar</label><input id="authConfirm" type="password" minlength="6" required autocomplete="new-password"></div>':'';
 const setupField=setup?'<div class="auth-field"><label>Ana Admin ilk kurulum kodu</label><input id="authBootstrap" required autocomplete="off"></div>':'';
 const actionText=setup?"Ana Admini Etkinleştir":register?"Hesap Oluştur":"Giriş Yap";
 card.innerHTML=`<div class="auth-logo">MCU TRACKER</div><div class="auth-sub">${sub}</div><div class="auth-tabs"><button id="loginTab" class="${mode==="login"?"active":""}" type="button">Giriş Yap</button><button id="registerTab" class="${register?"active":""}" type="button">Kayıt Ol</button><button id="setupTab" class="${setup?"active":""}" type="button">Ana Admin</button></div><form id="authForm">${displayField}<div class="auth-field"><label>Kullanıcı adı</label><input id="authUsername" minlength="3" maxlength="24" required autocomplete="username" ${userExtra}></div><div class="auth-field"><label>Şifre</label><input id="authPassword" type="password" minlength="6" required autocomplete="${register||setup?"new-password":"current-password"}"></div>${confirmField}${setupField}<button class="auth-submit" type="submit">${actionText}</button><div class="auth-error" id="authError"></div></form><div class="auth-note">Hesap ve admin rolleri merkezi sunucuda tutulur. İzleme, XP ve not verileri şimdilik cihazında kalır.</div>`;
 document.getElementById("loginTab").onclick=()=>renderAuth("login");document.getElementById("registerTab").onclick=()=>renderAuth("register");document.getElementById("setupTab").onclick=()=>renderAuth("setup");
 document.getElementById("authForm").onsubmit=async e=>{e.preventDefault();const err=document.getElementById("authError"),btn=e.submitter;err.textContent="";if(btn){btn.disabled=true;btn.textContent="Bağlanıyor…"}try{const name=document.getElementById("authUsername").value.trim(),pass=document.getElementById("authPassword").value;if(pass.length<6)throw new Error("Şifre en az 6 karakter olmalı.");let result;if(register||setup){const conf=document.getElementById("authConfirm").value;if(pass!==conf)throw new Error("Şifreler eşleşmiyor.");const display=register?(document.getElementById("authDisplay").value.trim()||name):"ovztur";const code=setup?document.getElementById("authBootstrap").value.trim():"";result=await centralRegister(name,pass,display,code)}else result=await centralLogin(name,pass);centralApplyUser(result)}catch(ex){const map={reserved_username:"ovztur adı yalnızca Ana Admin kurulumu ile oluşturulabilir.",username_exists:"Bu kullanıcı adı zaten kayıtlı.",bad_bootstrap_code:"Ana Admin kurulum kodu hatalı.",already_initialized:"Ana Admin hesabı zaten oluşturulmuş.",invalid_username:"Kullanıcı adı geçersiz.",weak_password:"Şifre en az 6 karakter olmalı."};const msg=ex?.message||"Bağlantı hatası.";err.textContent=map[msg]||(msg.includes("Invalid login")?"Kullanıcı adı veya şifre hatalı.":msg)}finally{if(btn){btn.disabled=false;btn.textContent=actionText}}};
};
logout=function(){clearCentralSession();localStorage.removeItem(sessionKey);currentUser=null;state=blankState();document.getElementById("sideMenu").classList.remove("open");document.getElementById("menuOverlay").classList.remove("open");showAuth("login")};
bootstrapAuth=async function(){try{const s=loadCentralSession();if(!s){showAuth("login");return}centralApplyUser(await centralProfile(s))}catch(e){console.warn("Merkezi oturum doğrulanamadı",e);clearCentralSession();showAuth("login")}};
async function centralProfiles(){let s=loadCentralSession();if(!s)throw new Error("no_session");try{return await centralJson(MCU_SB_URL+"/rest/v1/mcu_profiles?select=id,username,display_name,role&order=username.asc",{headers:centralHeaders(s.access_token)})}catch(e){if(e.status===401){s=await refreshCentralSession(s);return centralJson(MCU_SB_URL+"/rest/v1/mcu_profiles?select=id,username,display_name,role&order=username.asc",{headers:centralHeaders(s.access_token)})}throw e}}
setAccountAdmin=async function(key,makeAdmin){if(!isSuperAdmin()){alert("Bu işlem yalnızca ovztur Ana Admin hesabında yapılabilir.");return}if(userKey(key)==="ovztur"){alert("ovztur Ana Admin hesabının adminliği kaldırılamaz.");return}if(!confirm(`${key} hesabı ${makeAdmin?"Admin yapılsın mı?":"normal kullanıcıya çevrilsin mi?"}`))return;try{let s=loadCentralSession();await centralJson(MCU_SB_URL+"/rest/v1/rpc/mcu_set_admin",{method:"POST",headers:centralHeaders(s.access_token),body:JSON.stringify({target_username:userKey(key),make_admin:!!makeAdmin})});renderAdminPanel()}catch(e){alert("Yetki değiştirilemedi: "+(e.message||e))}};
renderAdminPanel=async function(){if(!isAdmin()){currentCategory="doomsday";renderCurrent();return}document.getElementById("subtitle").textContent=TITLES.admin;document.getElementById("movieList").innerHTML='<section class="panel"><b>Merkezi Admin Paneli yükleniyor…</b></section>';document.getElementById("loadMore").classList.add("hidden");try{const list=await centralProfiles(),admins=list.filter(u=>u.role==="admin"||u.role==="superadmin");const rows=list.map(u=>{const primary=u.username==="ovztur",admin=u.role==="admin"||u.role==="superadmin";return `<div class="panel" style="display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap"><div><b>${escapeHTML(u.display_name||u.username)}</b> <span class="meta">@${escapeHTML(u.username)}</span><div style="margin-top:6px"><span class="role-badge ${admin?"admin":""}">${primary?"🛡️ Ana Admin":admin?"👑 Admin":"👤 Kullanıcı"}</span></div></div><div>${primary?'<button class="secondary" disabled>Kalıcı Ana Admin</button>':isSuperAdmin()?`<button data-admin-key="${escapeHTML(u.username)}" data-admin-action="${admin?"remove":"grant"}" class="${admin?"secondary":""}">${admin?"Adminliği Kaldır":"Admin Yap"}</button>`:'<span class="meta">Yetki yönetimi yalnızca ovztur hesabında.</span>'}</div></div>`}).join("");document.getElementById("movieList").innerHTML=`<section class="profile-hero" style="grid-template-columns:72px 1fr"><div class="profile-avatar">🛡️</div><div><div class="profile-name">Merkezi Admin Paneli</div><div class="profile-rank">${isSuperAdmin()?"Ana Admin • ovztur":"Yetkili Admin"}</div><p class="meta" style="margin:8px 0 0">Toplam merkezi hesap: ${list.length} • Admin: ${admins.length}</p></div></section>${rows}`;document.querySelectorAll("[data-admin-action]").forEach(btn=>btn.onclick=()=>setAccountAdmin(btn.dataset.adminKey,btn.dataset.adminAction==="grant"))}catch(e){document.getElementById("movieList").innerHTML=`<section class="panel"><b>Admin verileri alınamadı.</b><p class="meta">${escapeHTML(e.message||String(e))}</p></section>`}};
